package app.rwun;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.android.controller.ActivityController;import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;
import static org.junit.Assert.*;
/** Host-side native Android rendering. Does not substitute for adb / Samsung acceptance. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35, qualifiers="w393dp-h852dp-mdpi",manifest=Config.NONE)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
@LooperMode(LooperMode.Mode.PAUSED)
public class NativePlanningTest {
 static <T extends View> T find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return (T)v;if(v instanceof ViewGroup){for(int i=0;i<((ViewGroup)v).getChildCount();i++){T result=find(((ViewGroup)v).getChildAt(i),text);if(result!=null)return result;}}return null;}
 static void click(Activity a,String text){View v=find(a.getWindow().getDecorView(),text);assertNotNull("Missing "+text,v);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();assertTrue(v.performClick());org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 static void shot(Activity a,String name)throws Exception{View v=a.getWindow().getDecorView();int w=393,h=852;v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));File f=new File(System.getProperty("rwun.evidence"),name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}bitmap.recycle();}
 @Test public void planningFlow()throws Exception{
  try(ActivityController<RacePlanActivity> controller=Robolectric.buildActivity(RacePlanActivity.class,new Intent().putExtra("mode","goal")).setup().visible()){
   RacePlanActivity a=controller.get();shot(a,"01-goals");click(a,"Race");shot(a,"02-race-search");View raceTitle=find(a.getWindow().getDecorView(),"Totalsports Two Oceans Half Marathon");assertNotNull(raceTitle);assertTrue("cover must not stretch to bitmap height",((View)raceTitle.getParent().getParent()).getHeight()<240);click(a,"Don't see your race?");shot(a,"03-manual-race");Button add=find(a.getWindow().getDecorView(),"Add race");assertFalse("incomplete race must be disabled",add.isEnabled());a.onBackPressed();a.onBackPressed();click(a,"Run a specific distance");shot(a,"04-distances");click(a,"10 km");assertNotNull(find(a.getWindow().getDecorView(),"Start with your actual running"));shot(a,"05-fitness");click(a,"Continue");shot(a,"06-availability");click(a,"Preview my plan");shot(a,"07-preview");assertNotNull(find(a.getWindow().getDecorView(),"Create my plan"));
  }
 }
 @Test public void manualRaceValidationAndRotation()throws Exception{
  try(ActivityController<RacePlanActivity> controller=Robolectric.buildActivity(RacePlanActivity.class,new Intent().putExtra("mode","search")).setup().visible()){
   RacePlanActivity a=controller.get();click(a,"Don't see your race?");edit(a,"Race name").setText("My autumn 10 km");edit(a,"City").setText("Cape Town");click(a,"Choose a date");DatePickerDialog date=(DatePickerDialog)org.robolectric.shadows.ShadowDialog.getLatestDialog();java.time.LocalDate target=java.time.LocalDate.now().plusWeeks(16);date.updateDate(target.getYear(),target.getMonthValue()-1,target.getDayOfMonth());date.getButton(-1).performClick();click(a,"Choose distance");AlertDialog distances=(AlertDialog)org.robolectric.shadows.ShadowDialog.getLatestDialog();distances.getListView().performItemClick(null,1,1);Button add=find(a.getWindow().getDecorView(),"Add race");assertTrue("valid details enable Add",add.isEnabled());click(a,"Add race");assertNotNull(find(a.getWindow().getDecorView(),"Start with your actual running"));controller.recreate();a=controller.get();assertNotNull(find(a.getWindow().getDecorView(),"Start with your actual running"));click(a,"Continue");click(a,"Preview my plan");assertNotNull(find(a.getWindow().getDecorView(),"My autumn 10 km"));shot(a,"09-race-preview");
  }
 }
 static EditText edit(Activity a,String description){return editView(a.getWindow().getDecorView(),description);}
 static EditText editView(View v,String description){if(v instanceof EditText&&description.contentEquals(v.getContentDescription()))return (EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText result=editView(((ViewGroup)v).getChildAt(i),description);if(result!=null)return result;}return null;}
 @Test public void planHub()throws Exception{android.app.Application application=RuntimeEnvironment.getApplication();TrackingService tracking=Robolectric.buildService(TrackingService.class).create().get();org.robolectric.Shadows.shadowOf(application).setComponentNameAndServiceForBindService(new ComponentName(application,TrackingService.class),tracking.onBind(new Intent()));new RunStore(application).save(new PlanEngine.Config(8,3,12,5,java.time.LocalDate.now()));try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup().visible()){click(controller.get(),"Plan");shot(controller.get(),"10-plan-hub");assertNotNull(find(controller.get().getWindow().getDecorView(),"Start new plan"));}}
 @Test public void largeFontLayout()throws Exception{RuntimeEnvironment.setFontScale(1.6f);try(ActivityController<RacePlanActivity> controller=Robolectric.buildActivity(RacePlanActivity.class,new Intent().putExtra("mode","search")).setup().visible()){shot(controller.get(),"11-races-large-font");click(controller.get(),"Don't see your race?");shot(controller.get(),"12-manual-large-font");}finally{RuntimeEnvironment.setFontScale(1f);}}
 @Test public void localCoachScreen()throws Exception{try(ActivityController<OfflineCoachActivity> controller=Robolectric.buildActivity(OfflineCoachActivity.class).setup().visible()){shot(controller.get(),"08-offline-coach");assertNotNull(find(controller.get().getWindow().getDecorView(),"Import downloaded model"));}}
}
